        let handle1x = self.locks[l1x].acquire_read();

        let mut i: usize = 0;
        while i < WIDTH
            invariant 0 <= i <= WIDTH,
                row_store_wf(self.consts@, handle1x@.rows[row as nat], row as nat),
                forall |j| 0 <= j < i ==>
